        private static void Check(bool ok,string label){if(!ok)throw new Exception(label);count++;File.AppendAllText(Path.Combine(folder,"checks.txt"),"PASS "+label+Environment.NewLine);}
        private sealed class BlurPattern : FrameworkElement
        {
            protected override void OnRender(DrawingContext dc){dc.DrawRectangle(Brushes.Black,null,new Rect(0,0,ActualWidth,ActualHeight));for(int x=0;x<ActualWidth;x+=4)dc.DrawRectangle(Brushes.White,null,new Rect(x,0,2,ActualHeight));}
        }
        private static double StripeVariation(string file)
        {using(var bmp=new System.Drawing.Bitmap(file)){var values=new List<double>();for(int x=40;x<bmp.Width-40;x++)values.Add(bmp.GetPixel(x,bmp.Height/2).R);double mean=values.Average();return Math.Sqrt(values.Average(v=>(v-mean)*(v-mean)));}}
