            string morning=Path.Combine(folder,"earth-08.jpg"),evening=Path.Combine(folder,"earth-20.jpg");var timer=Stopwatch.StartNew();await AstronomyWallpaper.RenderAsync(morning,new DateTime(2026,10,21,8,0,0),960,540);await AstronomyWallpaper.RenderAsync(evening,new DateTime(2026,10,21,20,0,0),960,540);long elapsed=timer.ElapsedMilliseconds;
            using(var a=new System.Drawing.Bitmap(morning))using(var b=new System.Drawing.Bitmap(evening)){long difference=0,lit=0;for(int y=80;y<460;y+=4)for(int x=280;x<680;x+=4){var p=a.GetPixel(x,y);var q=b.GetPixel(x,y);difference+=Math.Abs(p.R-q.R)+Math.Abs(p.G-q.G)+Math.Abs(p.B-q.B);if(p.R+p.G+p.B>45)lit++;}Check(lit>1000&&difference>50000,"Tierra renderiza una esfera texturada y cambia de hemisferio según la hora");Check(a.GetPixel(0,0).R<5&&a.Width==960&&b.Height==540,"fondo astronómico conserva espacio negro y tamaño acotado");}File.AppendAllText(Path.Combine(folder,"checks.txt"),"INFO dos fondos Tierra 960x540: "+elapsed+" ms; sin cambiar el fondo de Windows"+Environment.NewLine);
            var presence=new AssistantPresence(desktop);try{var frames=Path.Combine(folder,"assistant-presence");Directory.CreateDirectory(frames);presence.Update(AssistantStage.Appearance,"");for(int i=0;i<56;i++){if(i==14){presence.Update(AssistantStage.Listening,"Te escucho…");Check(!presence.ActionsAvailable,"los botones del asistente no invaden la esfera mientras empieza a expandirse");}if(i==33){presence.Update(AssistantStage.Working,"Consultando fuentes…");Check(presence.ActionsAvailable,"la banda expandida habilita escribir y cerrar con el espacio disponible");}if(i==43)presence.Update(AssistantStage.Hidden,null);await Task.Delay(30);var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(Design.Brush("#7385A4"),null,new Rect(0,0,520,110));if(presence.View.IsVisible){dc.PushOpacity(presence.View.Opacity);dc.DrawRectangle(new VisualBrush(presence.Surface),null,new Rect((520-presence.Surface.Width)/2,16,presence.Surface.Width,presence.Surface.Height));dc.Pop();}}var bmp=new System.Windows.Media.Imaging.RenderTargetBitmap(520,110,96,96,PixelFormats.Pbgra32);bmp.Render(visual);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bmp));using(var file=File.Create(Path.Combine(frames,i.ToString("D2")+".png")))encoder.Save(file);}Check(!presence.View.IsVisible&&!presence.Rendering,"cerrar la presencia separada retira su ventana y callbacks");presence.Update(AssistantStage.Listening,"Orden de prueba");await Task.Delay(80);presence.Update(AssistantStage.Hidden,null);await Task.Delay(50);presence.Update(AssistantStage.Appearance,"");await Task.Delay(650);Check(presence.View.IsVisible&&Math.Abs(presence.Surface.Width-74)<1,"reabrir durante salida cancela el cierre pendiente, sin duplicar la esfera");await Program.CaptureOwnWindow(presence.View,Path.Combine(folder,"assistant-sphere.png"));presence.Update(AssistantStage.Answer,"Listo para ayudarte");await Task.Delay(650);await Program.CaptureOwnWindow(presence.View,Path.Combine(folder,"assistant-band.png"));}finally{presence.Dispose();}
