        private static async Task CheckStableSurface()
        {
            var view=new Window{Title="Fixture de superficie estable",Width=500,Height=300,Left=220,Top=100,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,ShowInTaskbar=false,ShowActivated=false};var plate=new Border{Width=190,Height=34,Background=Brushes.Black,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Top};view.Content=plate;view.Show();await Task.Delay(100);int resize=0;view.SizeChanged+=delegate{resize++;};var motion=new IslandMotion(view,plate,delegate{},true,true);try{motion.To(416,258);await Task.Delay(60);motion.To(190,34);await Task.Delay(70);motion.To(416,258);await Task.Delay(1050);Check(resize==0&&view.Width==500&&view.Height==300&&plate.Width==416&&plate.Height==258,"expansión invertida mantiene el HWND estable y anima sólo su superficie");motion.To(190,34);await Task.Delay(900);Check(!motion.Running&&plate.Height==34,"superficie compacta termina sin renderizador ni dimensiones residuales");Native.RECT frame;var handle=new WindowInteropHelper(view).Handle;Native.GetWindowRect(handle,out frame);double scale=(frame.Right-frame.Left)/view.Width;var inside=new PixelPoint{X=(frame.Left+frame.Right)/2,Y=frame.Top+(int)(17*scale)};if(WindowFromPoint(inside)==handle)Check(WindowFromPoint(new PixelPoint{X=frame.Left+(int)(12*scale),Y=frame.Top+(int)(150*scale)})!=handle,"la zona transparente del marco estable deja pasar la entrada a otras ventanas");else File.AppendAllText(Path.Combine(folder,"checks.txt"),"PENDING prueba de paso de entrada ocluida por otra ventana"+Environment.NewLine);}finally{motion.Dispose();WindowLife.Close(view);}
        }
        private static async Task CheckCapsuleMotion()
        {
            double at60=126,v60=0,at120=126,v120=0,peak=126;
            for(int i=0;i<60;i++){IslandMotion.Step(ref at60,ref v60,388,1.0/60);peak=Math.Max(peak,at60);}
            for(int i=0;i<120;i++)IslandMotion.Step(ref at120,ref v120,388,1.0/120);
            Check(Math.Abs(at60-at120)<.000001&&Math.Abs(at60-388)<.01&&peak>389&&peak<392,"isla mantiene duración a 60/120 Hz y sobrepaso físico inferior al 1.5%");
            double panelPeak=0;for(int sample=0;sample<=1000;sample++)panelPeak=Math.Max(panelPeak,SpringEase.Progress(sample/1000.0));Check(panelPeak>1.01&&panelPeak<1.035&&SpringEase.Progress(1)==1,"los paneles frenan con un rebote corto y terminan en su posición exacta");double value=126,velocity=0;IslandMotion.Step(ref value,ref velocity,388,.05);double before=value;IslandMotion.Step(ref value,ref velocity,126,.0001);
            Check(Math.Abs(value-before)<1&&velocity>0,"invertir la isla conserva velocidad y continuidad sin saltar al inicio");
            var fixture=Design.Panel("Isla · fixture de resorte",126,30);fixture.Left=200;fixture.Top=100;fixture.ShowActivated=false;var shell=new Border{Background=Brushes.Black};fixture.Content=shell;fixture.Show();
            var motion=new IslandMotion(fixture,shell,delegate{});
            try{motion.To(388,204,130);await Task.Delay(55);motion.To(126,30,100);await Task.Delay(55);motion.To(388,204,130);await Task.Delay(1050);File.AppendAllText(Path.Combine(folder,"checks.txt"),"INFO resorte activo="+motion.Running+" ancho="+fixture.Width+" alto="+fixture.Height+" top="+fixture.Top+Environment.NewLine);Check(!motion.Running&&fixture.Width==388&&fixture.Height==204&&Math.Abs(fixture.Top-130)<=1,"abrir cerrar y reabrir la isla termina exactamente y retira el renderizador");motion.To(126,30);bool animations=Design.Animations;try{Design.Animations=false;await Task.Delay(90);Check(!motion.Running&&fixture.Width==126&&fixture.Height==30,"activar movimiento reducido durante expansión detiene y completa el resorte");}finally{Design.Animations=animations;}}
            finally{motion.Dispose();WindowLife.Close(fixture);}
        }
        private static async Task CheckPageTransition()
