        private static async Task CheckControlLevels(Desktop desktop)
        {
            string saved=desktop.Preferences.ControlCenterLayout;
            try{foreach(string layout in new[]{"Mac"}){desktop.Preferences.ControlCenterLayout=layout;var backend=new ControlFixture();var control=new ControlCenter(desktop,backend);control.ShowActivated=false;control.Show();try{await Task.Delay(300);if(Environment.OSVersion.Version.Build<22000&&!CompositorGlass.Active(control))Check(control.Tag!=null&&control.Tag.ToString().IndexOf("fallback",StringComparison.OrdinalIgnoreCase)>=0,"Centro de control informa alternativa en sistema anterior a Windows 11");else Check(CompositorGlass.Active(control),"compositor con desenfoque nativo activo, sin fallback silencioso");var slider=control.VolumeSlider;slider.ApplyTemplate();var track=(System.Windows.Controls.Primitives.Track)slider.Template.FindName("PART_Track",slider);bool vertical=slider.Orientation==Orientation.Vertical;Check(track!=null&&(vertical?track.ValueFromPoint(new Point(32,30))>track.ValueFromPoint(new Point(32,120)):track.ValueFromPoint(new Point(slider.ActualWidth*.75,10))>track.ValueFromPoint(new Point(slider.ActualWidth*.25,10))),"regulador conserva dirección y pista interactiva · "+layout);slider.Value=73;await Task.Delay(120);Check(backend.VolumeWrites>0&&Math.Abs(backend.State.Volume-73)<.1,"regulador envía volumen al proveedor sin escritura por cuadro · "+layout);}finally{WindowLife.Close(control);}}}finally{desktop.Preferences.ControlCenterLayout=saved;}
        }
