        internal static int Run(string directory)
        {
            folder=Path.GetFullPath(directory);Directory.CreateDirectory(folder);Log.DirectoryPath=folder;File.WriteAllText(Path.Combine(folder,"checks.txt"),"");
            var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Desktop desktop=null;Window background=null,fixture=null;ActivityIsland island=null;GlassNotifications notifications=null;PrivacyScreen privacy=null;
            Action<Exception> fail=ex=>File.AppendAllText(Path.Combine(folder,"checks.txt"),"FAIL "+ex+Environment.NewLine);
            app.DispatcherUnhandledException+=delegate(object s,System.Windows.Threading.DispatcherUnhandledExceptionEventArgs e){fail(e.Exception);e.Handled=true;app.Shutdown(1);};
            app.Startup+=async delegate
            {
                try
                {
                    Motion.TestClientAreaAnimations=true;await CheckStableSurface();await CheckPageTransition();await CheckCapsuleMotion();await AssistantMotionPreview();
                    var timer=Stopwatch.StartNew();var profile=Path.Combine(folder,"profile");new SettingsStore(profile).Save(new Preferences{ContainedDockApplied=true,AppleDesign27Applied=true,KeyboardSearchApplied=true,Theme="Light",HideDockInApps=false,HideDockInCodex=false,AutoHideTaskbar=false,HideInFullscreen=false,CheckUpdatesAutomatically=false,VoiceWakeEnabled=false});desktop=new Desktop(profile,true,true);timer.Stop();await CheckEarthAndPresence(desktop);
                    Check(!new Preferences().VoiceWakeEnabled.GetValueOrDefault(),"un perfil nuevo no activa el micrófono sin elegirlo");Check(!new Preferences().ShowSessionGreeting.GetValueOrDefault(),"un perfil nuevo no inicia Hola al entrar a Windows");
                    background=new VisualTestBackground{WindowState=WindowState.Normal,Width=SystemParameters.PrimaryScreenWidth,Height=SystemParameters.PrimaryScreenHeight,Left=0,Top=0,WindowStyle=WindowStyle.None,ShowActivated=false};background.Content=new Image{Source=new System.Windows.Media.Imaging.BitmapImage(new Uri(WallpaperLibrary.Load(profile)[0].File)),Stretch=Stretch.UniformToFill};background.SourceInitialized+=delegate{Native.NoActivate(background);};background.Show();await CheckNativeBlur((VisualTestBackground)background);await CheckControlLevels(desktop);
                    foreach(var area in new[]{new DisplayArea("left",new Rect(-1920,-200,1920,1080),1.25),new DisplayArea("right",new Rect(1920,0,2560,1440),1.5),new DisplayArea("small",new Rect(0,0,1024,768),1)}){var rect=DisplaySpace.Center(area,new Size(480,400),.15);Check(rect.Left>=area.WorkingDips.Left&&rect.Right<=area.WorkingDips.Right&&rect.Bottom<=area.WorkingDips.Bottom,"panel contenido con origen negativo y DPI · "+area.Device);}
                    for(int i=0;i<10;i++){desktop.OpenControl();var panel=desktop.Control;Design.Reveal(panel);Design.Dismiss(panel);desktop.OpenControl();Check(WindowLife.Alive(desktop.Control)&&desktop.Control!=panel,"reabrir durante cierre recrea el panel · "+i);WindowLife.Close(desktop.Control);}
                    for(int i=0;i<8;i++){var previous=desktop.CreateGestureControl();var next=desktop.CreateGestureControl();ControlPullGesture.Settle(previous,true);ControlPullGesture.Settle(next,true);Check(!WindowLife.Alive(previous)&&WindowLife.Alive(next),"dos gestos no superponen centros · "+i);WindowLife.Close(next);}
                    foreach(string state in new[]{"Light|Mac","Dark|Mac"})
                    {
                        var parts=state.Split('|');string theme=parts[0];desktop.Preferences.ControlCenterLayout=parts[1];desktop.Preferences.Theme=theme;desktop.ApplyPreferences(desktop.Preferences,null);desktop.OpenControl();await Task.Delay(650);var panel=(ControlCenter)desktop.Control;var slider=panel.VolumeSlider;var point=slider.TransformToAncestor(panel).Transform(new Point(slider.ActualWidth,0));Check(point.X<=panel.ActualWidth&&(parts[1]=="iPad"?slider.Orientation==Orientation.Vertical&&slider.ActualWidth>=60&&slider.ActualWidth<=80&&slider.ActualHeight>=140&&slider.ActualHeight<=160:slider.Orientation==Orientation.Horizontal&&slider.ActualWidth>200&&slider.ActualHeight<=24),"reguladores contenidos sin columnas superpuestas · "+theme+" · "+parts[1]);await Program.CaptureOwnWindow(panel,Path.Combine(folder,"control-"+theme+"-"+parts[1]+".png"));if(parts[1]=="Mac")File.Copy(Path.Combine(folder,"control-"+theme+"-Mac.png"),Path.Combine(folder,"control-"+theme+".png"),true);WindowLife.Close(panel);
                        desktop.OpenSettings();await Task.Delay(350);await Program.CaptureOwnWindow(desktop.Settings,Path.Combine(folder,"settings-"+theme+".png"));WindowLife.Close(desktop.Settings);
                    }
                    var navigationCheck=new SettingsWindow(desktop,true){ShowActivated=false};navigationCheck.Show();for(int page=0;page<17;page++){navigationCheck.SelectPage(page);await Task.Delay(65);Check(WindowLife.Alive(navigationCheck),"ajustes navegables sin excepciones · página "+page);}navigationCheck.SelectPage(6);await Task.Delay(250);await Program.CaptureOwnWindow(navigationCheck,Path.Combine(folder,"settings-notch.png"));navigationCheck.SelectPage(16);await Task.Delay(250);await Program.CaptureOwnWindow(navigationCheck,Path.Combine(folder,"settings-transfer.png"));WindowLife.Close(navigationCheck);
                    desktop.Preferences.ControlCenterLayout="Auto";var settingsCheck=new SettingsWindow(desktop,true);desktop.Preferences.SetDockAutoHide(true);desktop.Preferences.HideDockInApps=desktop.Preferences.HideDockInCodex=true;settingsCheck.SetDockAutoHide(false);var savedBehavior=new SettingsStore(profile).Load();Check(!savedBehavior.AnyDockAutoHide&&!savedBehavior.HideInFullscreen,"no ocultar Dock guarda inmediatamente todas las reglas sin Aplicar");WindowLife.Close(settingsCheck);
